using System;
using System.IO;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;

static async Task SendAllAsync(
    Socket socket, ReadOnlyMemory<byte> payload, CancellationToken ct)
{
    int offset = 0;
    while (offset < payload.Length)
    {
        int sent = await socket.SendAsync(
            payload[offset..], SocketFlags.None, ct);
        if (sent == 0) throw new IOException("send made no progress");
        offset += sent;
    }
}

static async Task<int> ReadOneAvailableChunkAsync(
    NetworkStream stream, byte[] buffer, CancellationToken ct)
{
    if (buffer.Length == 0) throw new ArgumentException("buffer must be non-empty");
    int n = await stream.ReadAsync(buffer.AsMemory(), ct);
    if (n == 0) return 0; // 此例 buffer 長度大於 0：對端正常結束傳送方向
    ProcessBytes(buffer.AsSpan(0, n)); // 應用 parser；只讀本次實際填入的範圍
    return n;
}

using System;
using System.Net.Sockets;
using System.Threading;

while (!ct.IsCancellationRequested)
{
    UdpReceiveResult result;
    try
    {
        result = await udp.ReceiveAsync(ct);
    }
    catch (OperationCanceledException) when (ct.IsCancellationRequested)
    {
        break; // 服務生命週期正常停止
    }
    Console.WriteLine(
        $"datagram bytes={result.Buffer.Length} from={result.RemoteEndPoint}");

    if (result.Buffer.Length == 0)
    {
        // 依應用格式政策記錄／拒絕這筆空資料報；不要當成 TCP EOF 離開接收迴圈。
        continue;
    }

    ValidateAndHandle(result.Buffer, result.RemoteEndPoint); // 應用層函式
}
